mapper.select:
SELECT * FROM t_spd_apply
WHERE del_flag = #{delFlag}

    AND apply_no LIKE CONCAT('%', #{query.applyNo}, '%')


    AND apply_dept_id = #{query.applyDeptId}


    AND apply_status = #{query.applyStatus}


    AND apply_time >= #{query.applyTimeStart}


    AND apply_time <= #{query.applyTimeEnd}

ORDER BY create_time DESC
